contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address sender, uint preBalance, uint unlockTime) public payable {
        require(sender != address(c));
        require(msg.sender != sender);

        // Ensure the state carried into the deciding Put is what we think it is.
        uint128 acc = c.Acc(sender).balance;
        require(acc == preBalance, "need clean sender state");

        uint cBalBefore = address(c).balance;
        require(address(this).balance >= msg.value, "not enough ether");

        bool reverted;
        try c.Put{value: msg.value}(unlockTime) { reverted = false; }
        catch { reverted = true; }

        if (reverted) {
            assert(c.Acc(sender).balance == acc && address(c).balance == cBalBefore);
        } else {
            assert(c.Acc(sender).balance == acc + msg.value && address(c).balance == cBalBefore + msg.value);
        }
    }

    receive() external payable {}
}

